INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(118009, 'ruRU', '', 'Твоя убеждённость позволяет исцелять себя и союзников. Вспышка света — основа твоего арсенала исцеления.', 24330),
(118010, 'ruRU', '', 'Божественный щит защитил тебя от первой атаки мага, но вторая атака оставила тебя раненым.', 24330),
(118011, 'ruRU', '', 'Божественный щит полностью защитит тебя от всех атак на короткое время, так что сохрани его для крайних случаев.', 24330),
(118012, 'ruRU', '', 'Используй Божественный щит, чтобы сделать себя временно неуязвимым для любого урона!', 24330),
(118013, 'ruRU', '', 'Божественный щит не даёт входящим атакам нанести тебе вред.', 24330),
(118014, 'ruRU', '', 'Тебе предстоит множество опасных ситуаций, и подготовка может стать ключом к твоему выживанию.', 24330),
(118015, 'ruRU', '', 'У тебя уже максимум Святой силы! Используй Вердикт тамплиера!', 24330),
(118016, 'ruRU', '', 'Используй Вердикт тамплиера!', 24330),
(118017, 'ruRU', '', 'Вердикт тамплиера доступен! Используй его сейчас!', 24330),
(118018, 'ruRU', '', 'Используй Правосудие!', 24330),
(118019, 'ruRU', '', 'Правосудие доступно! Используй его сейчас!', 24330),
(118020, 'ruRU', '', 'Правосудие — способность дальнего действия. Попробуй применить её с большего расстояния!', 24330),
(118021, 'ruRU', '', 'Используй Вспышку света, чтобы исцелить себя!', 24330),
(118022, 'ruRU', '', 'Используй Божественный щит!', 24330),
(118023, 'ruRU', '', 'Ты в беде! Используй Божественный щит, чтобы спастись!', 24330),
(118024, 'ruRU', '', 'Используй Удар крестоносца!', 24330),
(118025, 'ruRU', '', 'Используй Удар крестоносца, чтобы накопить Святую силу!', 24330),
(118026, 'ruRU', '', 'Используй Клинок правосудия!', 24330),
(118027, 'ruRU', '', 'Клинок правосудия доступен! Используй его сейчас!', 24330),
(118028, 'ruRU', '', 'Отлично сделано, $p! Теперь ты готов сражаться как паладин воздаяния.', 24330),
(118029, 'ruRU', '', 'Покажи мне свою отвагу и рвение в пылу битвы!', 24330),
(118030, 'ruRU', '', 'Накопи Святую силу своими атаками, затем используй Вердикт тамплиера на этом тренировочном манекене.', 24330),
(118031, 'ruRU', '', 'Высвободи эту божественную магию через Вердикт тамплиера — мощную атаку в ближнем бою, что наполняет твоё оружие силой Света.', 24330),
(118032, 'ruRU', '', 'Использование Клинка правосудия и Удара крестоносца в бою накапливает Святую силу.', 24330),
(118033, 'ruRU', '', 'Используй Удар крестоносца на этом тренировочном манекене.', 24330),
(118034, 'ruRU', '', 'Как только враг приблизится на дистанцию удара, высвободи своё оружие Ударом крестоносца.', 24330),
(118035, 'ruRU', '', 'Клинок правосудия — отличный инструмент для нанесения урона, пока противник приближается.', 24330),
(118036, 'ruRU', '', 'Используй Клинок правосудия на этом тренировочном манекене.', 24330),
(118037, 'ruRU', '', 'Когда враг приближается, высвободи мощную атаку среднего радиуса под названием Клинок правосудия.', 24330),
(118038, 'ruRU', '', 'Правосудие можно использовать против врагов на расстоянии или вблизи, когда оно доступно.', 24330),
(118039, 'ruRU', '', 'Используй Правосудие на этом тренировочном манекене.', 24330),
(118040, 'ruRU', '', 'Твоя преданность Свету даёт тебе силу обрушить на врагов могучий молот Правосудия.', 24330),
(118041, 'ruRU', '', 'Твои атаки — сочетание заклинаний дальнего боя и ближних ударов, что накапливают и высвобождают Святую силу.', 24330),
(118042, 'ruRU', '', 'Будучи паладином воздаяния, ты стойкий защитник слабых, несущий возмездие несправедливым!', 24330),
(118043, 'ruRU', '', 'Используй Воззвание, чтобы исцелить свои раны.', 24330),
(118044, 'ruRU', '', 'Впрочем, для тебя это не проблема. Свет даёт тебе силу восстанавливать здоровье себе или своим союзникам.', 24330),
(118045, 'ruRU', '', 'Слово силы: Щит защитило тебя от первой атаки мага, но вторая атака оставила тебя раненым.', 24330),
(118046, 'ruRU', '', 'Используй Болевой крик, чтобы не дать этой группе врагов ударить тебя.', 24330),
(118047, 'ruRU', '', 'К счастью, в таких случаях ты не беззащитен. Болевой крик приводит в ужас находящихся рядом противников, заставляя их разбегаться в страхе.', 24330),
(118048, 'ruRU', '', 'В некоторых боях тебе придётся сражаться с несколькими противниками одновременно.', 24330);
